from ta_ue_plugin_rtg.rpc.rpc_call_wraped import RpcCall
from ute_common_abstract_core.network_elem_identification import MsgSourceIdentification
from ute_ue.lteuegroup import LteUeGroup
from ute_ue.exceptions import UeProcedureError
from ute_common_abstract_core.logger import active_loggers
import logging


class RtgUeGroup(LteUeGroup):
    """RtgUeGroup class provides ue-group implementation"""

    def __init__(self, ues, rpc_socket):
        """
        Construct RTG UE-group

        :param ues: UEs carried by group
        """
        super(RtgUeGroup, self).__init__(ues)
        self.rpc_call = RpcCall(rpc_socket, self.logger).call
        self._ids_of_group_ues = [ue.get_ue_id() for ue in self.ues]
        self._activate_msg_source()
        self._set_ues_files_handlers_to_group_handler()
        self._add_stream_handler_if_ute_ue_logger_not_created()
        self.attached = False

    def _activate_msg_source(self):
        MsgSourceIdentification(identifiers=[('rtg', 'RTG')], network_elem_type='UE', specific_for_tool='rtg')

    def _set_ues_files_handlers_to_group_handler(self):
        for ue in self.ues:
            ue.logger.logger.handlers = self.logger.handlers

    def _add_stream_handler_if_ute_ue_logger_not_created(self):
        if 'ute_ue' not in active_loggers:
            sfh = logging.StreamHandler()
            sfh.setLevel(level=30)
            self.logger.addHandler(sfh)

    def _set_ues_attached_flag(self, value):
        for ue in self.ues:
            ue.attached = value
        self.attached = value

    def _get_default_const_interval_and_intervals_list(self, rate, intervals):
        if bool(rate) and bool(intervals):
            raise ValueError("'rate' and 'intervals' cannot be provided both.")
        elif rate and intervals is None:
            default_const_interval = int(1000000 / int(rate))
        elif rate is None and intervals is None:
            default_const_interval = 25000
        else:
            default_const_interval = None
            if len(intervals) != len(self.ues):
                raise ValueError('Length of intervals list should be equal to number of ues in this group.')
            # intervals = map(lambda num: 1000000 if num == 0 else num, intervals)
            intervals = [1000000 if interval == 0 else interval for interval in intervals]

        return default_const_interval, intervals

    def _get_base_actions_for_each_ue(self):
        if self.attached is False:
            return [[('attach', None)] for _ in self.ues]
        else:
            return [[] for _ in self.ues]

    def _get_actions_for_each_ue(self, transmission_times, wait_till_go_idle):
        actions_for_each_ue = self._get_base_actions_for_each_ue()

        self._add_keep_active_for_each_ue_actions(actions_for_each_ue, transmission_times)

        if wait_till_go_idle:
            for one_ue_actions in actions_for_each_ue:
                one_ue_actions.append(('go_idle', None))

        if actions_for_each_ue == [[] for _ in self.ues]:
            raise ValueError('UEs will not take any action, please check provided arguments and UEs state')

        return actions_for_each_ue

    def _add_keep_active_for_each_ue_actions(self, actions_for_each_ue, transmission_times):
        if transmission_times is not None and len(transmission_times) != len(self.ues):
            raise ValueError('Length of activity times list should be equal to number of ues in this group.')
        elif transmission_times is not None:
            for one_ue_actions, activity_time in zip(actions_for_each_ue, transmission_times):
                one_ue_actions.append(('keep_active', activity_time))

    def _get_attach_params(self, rate, intervals, transmission_times, wait_till_go_idle):
        default_const_interval, intervals = self._get_default_const_interval_and_intervals_list(rate, intervals)
        actions_for_each_ue = self._get_actions_for_each_ue(transmission_times, wait_till_go_idle)

        if intervals:
            attach_descriptions_list = [{'ue_id': ue_id, 'interval': interval, 'actions': one_ue_actions} for ue_id, interval, one_ue_actions
                                        in zip(self._ids_of_group_ues, intervals, actions_for_each_ue)]
        else:
            attach_descriptions_list = [{'ue_id': ue_id, 'actions': one_ue_actions} for ue_id, one_ue_actions
                                        in zip(self._ids_of_group_ues, actions_for_each_ue)]

        return {'default_const_interval': default_const_interval, 'procedure_descriptions_list': attach_descriptions_list}

    def _handle_number_of_failures(self, number_of_failures, ignore_error, success_ratio=None, failure_ratio=None, warning_prefix=None):
        if sum([1 if val else 0 for val in [ignore_error, success_ratio, failure_ratio]]) > 1:
            raise ValueError('Each of ignore_error, success_ratio & failure_ratio can be provided only separately')

        if ignore_error and number_of_failures:
            self.logger.warning('{}: {}/{} procedures failed'.format(warning_prefix, number_of_failures, len(self.ues)))
        elif failure_ratio:
            actual_failure_ratio = 100 * float(number_of_failures) / len(self.ues)
            assert actual_failure_ratio == failure_ratio, 'Actual failure rate ({}%) differs from expected ({}%)'.\
                format(actual_failure_ratio, failure_ratio)
        elif success_ratio:
            actual_success_ratio = 100 - 100 * float(number_of_failures) / len(self.ues)
            assert actual_success_ratio == success_ratio, 'Actual success rate ({}%) differs from expected ({}%)'.\
                format(actual_success_ratio, success_ratio)
        elif number_of_failures:
            raise UeProcedureError('{}/{} procedures failed'.format(number_of_failures, len(self.ues)))

    def attach(self, rate=None, intervals=None, transmission_times=None, wait_till_go_idle=False,
               success_ratio=None, failure_ratio=None, ignore_error=False):
        """
        Either rate or intervals parameter can be provided (not both).
        :param rate: rrcConnectionRequests per second
        :param intervals: list of delays between each rrcConnectionRequests in microseconds. Zero is treated as 1 sec interval
        :param transmission_times: list of times UEs sending data in milliseconds
        :param wait_till_go_idle: boolean that determines if should wait till ues go idle
        :param success_ratio: float as %, can be provided with neither failure_ratio nor ignore_error
        :param failure_ratio: float as %, can be provided with neither success_ratio nor ignore_error
        :param ignore_error: boolean, can be provided with neither success_ratio nor failure_ratio
        :return:
        """
        if not self.attached:
            params = self._get_attach_params(rate, intervals, transmission_times, wait_till_go_idle)
            number_of_failures = self.rpc_call(method="perform_procedure_on_multiple_ues", params=params,
                                               log_msg="RtgUeGroup.attach")['number_of_failures']
            self._handle_number_of_failures(number_of_failures, ignore_error, success_ratio, failure_ratio, warning_prefix="RtgUeGroup.attach")
            self._set_ues_attached_flag(True)
        else:
            raise UeProcedureError('UEs are already attached')

    def exit_idle_mode(self, transmission_times, rate=None, intervals=None, ignore_error=False, **kwargs):
        """
        Either rate or intervals parameter can be provided (not both).
        :param rate: rrcConnectionRequests per second
        :param intervals: list of delays between each rrcConnectionRequests in microseconds
        :param transmission_times: list of times UEs sending data in milliseconds
        :param ignore_error:
        :param kwargs:
        :return:
        """
        if self.attached:
            params = self._get_attach_params(rate, intervals, transmission_times, False)
            number_of_failures = self.rpc_call(method="perform_procedure_on_multiple_ues",
                                               params=params,
                                               log_msg="RtgUeGroup.exit_idle_mode")['number_of_failures']
            self._handle_number_of_failures(number_of_failures, ignore_error, warning_prefix="RtgUeGroup.exit_idle_mode")
        else:
            raise UeProcedureError('UEs are not attached')

    def detach(self, **kwargs):
        """
        :param kwargs:
        :return:
        """
        detach_params = [{'ue_id': ue_id, 'actions': [('detach', None)]} for ue_id in self._ids_of_group_ues]
        number_of_failures = self.rpc_call(method="perform_procedure_on_multiple_ues",
                                           params={'procedure_descriptions_list': detach_params, 'default_const_interval': 20000},
                                           log_msg="RtgUeGroup.detach")['number_of_failures']
        self._handle_number_of_failures(number_of_failures, False)
        self._set_ues_attached_flag(False)

    def shutdown(self):
        """:return:"""
        detach_params = [{'ue_id': ue_id, 'actions': [('detach', None)]} for ue_id in self._ids_of_group_ues]
        self.rpc_call(method="perform_procedure_on_multiple_ues",
                      params={'procedure_descriptions_list': detach_params, 'default_const_interval': 20000},
                      log_msg="RtgUeGroup.shutdown")
        self._set_ues_attached_flag(False)

    def release(self):
        """:return:"""
        self.rpc_call(method="release_ues_from_id_list", params={'ue_ids_list': self._ids_of_group_ues}, log_msg="RtgUeGroup.release")
